(()=>{
'use strict';if(!document.body.classList.contains('shared-app'))return;
let from='',to='',memberId='',order='load';const previous=renderReports;
renderReports=function(){
 previous();if(!management())return;
 const root=el('#sharedContent'),presence=el('#presenceReport');if(presence)presence.remove();
 const filtered=tasks.filter(t=>{const d=t.due||(t.created_at||'').slice(0,10);return(!from||d>=from)&&(!to||d<=to)});
 const available=members.filter(m=>m.active||filtered.some(t=>t.owner_id===m.id));
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const rows=available.filter(m=>!memberId||m.id===memberId).map(m=>{const own=filtered.filter(t=>t.owner_id===m.id),counts=['open','review','done'].map(s=>own.filter(t=>t.status===s).length);return {m,own,counts,n:own.length,late:own.filter(t=>t.status!=='done'&&t.due&&t.due<today).length}});
 rows.sort((a,b)=>order==='name'?a.m.name.localeCompare(b.m.name,'fa'):order==='late'?b.late-a.late||b.n-a.n:b.n-a.n||a.m.name.localeCompare(b.m.name,'fa'));
 const total=filtered.filter(t=>!memberId||t.owner_id===memberId),count=s=>total.filter(t=>t.status===s).length,max=Math.max(1,...rows.map(r=>r.n));
 root.innerHTML='<section class="people-report"><div class="people-report-heading"><h2>گزارش وضعیت افراد</h2><label class="people-order">نمایش بر اساس<select id="peopleOrder"><option value="load">تعداد کارها</option><option value="late">کارهای عقب‌افتاده</option><option value="name">نام افراد</option></select></label></div><form id="peopleRange" class="range-controls"><label>مهلت از<input type="date" name="from" aria-label="شروع بازه گزارش" value="'+from+'"></label><label>مهلت تا<input type="date" name="to" aria-label="پایان بازه گزارش" value="'+to+'"></label><label>عضو پروژه<select name="member"><option value="">همه اعضا</option>'+available.map(m=>'<option value="'+esc(m.id)+'" '+(memberId===m.id?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><div class="people-range-actions"><button class="primary">اعمال بازه</button><button type="button" id="clearPeopleRange" class="secondary">همه زمان‌ها</button></div></form><div class="people-kpis">'+[['کل کارها',total.length],['در دست اقدام',count('open')],['منتظر تأیید',count('review')],['تأییدشده',count('done')]].map(([l,n])=>'<div><span>'+l+'</span><b>'+fa(n)+'</b></div>').join('')+'</div><div class="people-comparison"><div class="people-comparison-head"><span>عضو پروژه</span><span>حجم کار</span><span>در اقدام</span><span>تأیید</span><span>تکمیل</span><span>عقب‌افتاده</span></div>'+rows.map(({m,own,counts,n,late})=>'<article class="people-comparison-row"><button type="button" class="person-row-button" data-person-report="'+esc(m.id)+'" aria-expanded="false"><span class="person-name"><b>'+esc(m.name)+'</b><small>'+fa(n)+' کار'+(!m.active?' · غیرفعال':'')+'</small></span><span class="person-volume" role="img" aria-label="'+esc(m.name)+'؛ '+counts.map((c,i)=>labels[['open','review','done'][i]]+': '+fa(c)).join('، ')+'"><span class="person-volume-track">'+counts.map((c,i)=>c?'<i class="'+['open','review','done'][i]+'" style="width:'+c/max*100+'%"></i>':'').join('')+'</span></span><b class="person-count open">'+fa(counts[0])+'</b><b class="person-count review">'+fa(counts[1])+'</b><b class="person-count done">'+fa(counts[2])+'</b><b class="person-count '+(late?'overdue':'')+'">'+fa(late)+'</b></button><div class="person-report-tasks" hidden>'+(own.length?own.map(t=>'<button type="button" data-report-task="'+esc(t.id)+'"><span>'+esc(t.title)+'</span><small>'+esc(labels[t.status]||t.status)+(t.due?' · '+esc(SamandisDates.display(t.due)):'')+'</small></button>').join(''):'<p>کاری در این بازه ثبت نشده است.</p>')+'</div></article>').join('')+'</div></section>';
 if(presence)root.append(presence);
 el('#peopleOrder').value=order;el('#peopleOrder').onchange=e=>{order=e.target.value;renderReports()};
 el('#peopleRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(a&&b&&a>b)return message('تاریخ شروع باید قبل از پایان باشد.');from=a;to=b;memberId=f.get('member');renderReports()};
 el('#clearPeopleRange').onclick=()=>{from=to=memberId='';renderReports()};
 root.querySelectorAll('[data-person-report]').forEach(b=>b.onclick=()=>{const list=b.nextElementSibling;list.hidden=!list.hidden;b.setAttribute('aria-expanded',String(!list.hidden))});
 root.querySelectorAll('[data-report-task]').forEach(b=>b.onclick=()=>detail(b.dataset.reportTask));
};
})();
